#!/usr/bin/env python3"""Скрипт для миграции базы данных - добавление таблицы папок"""import sysimport os# Добавляем родительскую директорию в путь Pythonparent_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))sys.path.insert(0, parent_dir)from sqlmodel import Session, textfrom core.database import engine, create_db_and_tablesfrom models.folder import Folderfrom models.user import Userdef migrate_database():    """Выполнить миграцию базы данных"""    print("🔄 Начинаем миграцию базы данных...")        try:        # Создаем все таблицы (включая новую таблицу папок)        print("📋 Создаем таблицы...")        create_db_and_tables()        print("✅ Таблицы созданы успешно!")                # Проверяем, что таблица папок создана        with Session(engine) as session:            # Проверяем существование таблицы папок            result = session.exec(text("""                SELECT name FROM sqlite_master                 WHERE type='table' AND name='folder'            """)).first()                        if result:                print("✅ Таблица 'folder' создана успешно!")            else:                print("❌ Ошибка: таблица 'folder' не найдена!")                return False                print("🎉 Миграция завершена успешно!")        return True            except Exception as e:        print(f"❌ Ошибка при миграции: {e}")        return Falsedef create_default_folders():    """Создать папки по умолчанию для существующих пользователей"""    print("📁 Создаем папки по умолчанию...")        try:        with Session(engine) as session:            # Получаем всех пользователей            users = session.exec(text("SELECT id FROM user")).all()                        if not users:                print("ℹ️ Пользователи не найдены, пропускаем создание папок по умолчанию")                return True                        # Создаем системные папки для каждого пользователя            default_folders = [                {                    "name": "Персонажи",                    "description": "Чаты с персонажами",                    "folder_type": "system",                    "icon": "psychology",                    "color": "bg-purple-500",                    "is_pinned": True,                    "sort_order": 1                },                {                    "name": "Инструменты",                     "description": "Полезные инструменты",                    "folder_type": "system",                    "icon": "build",                    "color": "bg-green-500",                    "is_pinned": True,                    "sort_order": 2                },                {                    "name": "AI Модели",                    "description": "Искусственный интеллект",                    "folder_type": "system",                     "icon": "auto_awesome",                    "color": "bg-blue-500",                    "is_pinned": True,                    "sort_order": 3                }            ]                        created_count = 0            for user_id in users:                for folder_data in default_folders:                    # Проверяем, не существует ли уже такая папка                    existing = session.exec(text("""                        SELECT id FROM folder                         WHERE user_id = :user_id AND name = :name AND folder_type = :folder_type                    """), {                        "user_id": user_id[0],                        "name": folder_data["name"],                        "folder_type": folder_data["folder_type"]                    }).first()                                        if not existing:                        # Создаем папку                        session.exec(text("""                            INSERT INTO folder (                                name, description, folder_type, icon, color,                                 is_shared, is_pinned, sort_order, user_id,                                 chat_ids, agent_ids, settings, created_at, updated_at                            ) VALUES (                                :name, :description, :folder_type, :icon, :color,                                :is_shared, :is_pinned, :sort_order, :user_id,                                :chat_ids, :agent_ids, :settings, :created_at, :updated_at                            )                        """), {                            **folder_data,                            "user_id": user_id[0],                            "chat_ids": "[]",                            "agent_ids": "[]",                             "settings": "{}",                            "created_at": "datetime('now')",                            "updated_at": "datetime('now')"                        })                        created_count += 1                        session.commit()            print(f"✅ Создано {created_count} папок по умолчанию!")                except Exception as e:        print(f"❌ Ошибка при создании папок по умолчанию: {e}")        return False        return Trueif __name__ == "__main__":    print("🚀 Запуск миграции базы данных для папок")    print("=" * 50)        # Выполняем миграцию    if migrate_database():        # Создаем папки по умолчанию        create_default_folders()        print("\n🎉 Миграция завершена успешно!")    else:        print("\n❌ Миграция не удалась!")